def is_valid_parentheses(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

# Example: is_valid_parentheses('()[]{}') -> True
# Time: O(n), Space: O(n). Stack matches closing brackets to the latest opener.

def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t not in '+-*/':
            stack.append(int(t))
        else:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))
    return stack[0]

# Example: eval_rpn(['2','1','+','3','*']) -> 9
# Time: O(n), Space: O(n). Push operands; on operator, pop two and push result.

def remove_adjacent_duplicates(s):
    stack = []
    for ch in s:
        if stack and stack[-1] == ch:
            stack.pop()
        else:
            stack.append(ch)
    return ''.join(stack)

# Example: remove_adjacent_duplicates('abbaca') -> 'ca'
# Time: O(n), Space: O(n). Cancel pairs as they become adjacent on the stack.

from collections import deque

class MinQueue:
    def __init__(self):
        self.q = deque()
        self.mins = deque()
    def push(self, x):
        self.q.append(x)
        while self.mins and self.mins[-1] > x:
            self.mins.pop()
        self.mins.append(x)
    def pop(self):
        x = self.q.popleft()
        if self.mins and self.mins[0] == x:
            self.mins.popleft()
        return x
    def peek(self):
        return self.q[0]
    def get_min(self):
        return self.mins[0]

# Example: q = MinQueue(); q.push(3); q.push(1); q.get_min() -> 1; q.pop(); q.get_min() -> 3
# Time: O(1) amortized per op, Space: O(n). Monotonic deque tracks window minimums.

def letter_combinations_iter(digits):
    if not digits:
        return []
    mapping = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
    stack = [('', 0)]
    result = []
    while stack:
        path, index = stack.pop()
        if index == len(digits):
            result.append(path)
            continue
        for ch in reversed(mapping[digits[index]]):
            stack.append((path + ch, index + 1))
    return result

# Example: letter_combinations_iter('23') -> ['ad','ae','af','bd','be','bf','cd','ce','cf']
# Time: O(4^n * n), Space: O(4^n). Explicit stack DFS over keypad choices.

