class MyCircularQueue:
    def __init__(self, k):
        self.cap = k
        self.data = [None] * k
        self.head = 0
        self.size = 0
    def enQueue(self, value):
        if self.size == self.cap:
            return False
        self.data[(self.head + self.size) % self.cap] = value
        self.size += 1
        return True
    def deQueue(self):
        if self.size == 0:
            return False
        self.head = (self.head + 1) % self.cap
        self.size -= 1
        return True
    def Front(self):
        return -1 if self.size == 0 else self.data[self.head]
    def Rear(self):
        return -1 if self.size == 0 else self.data[(self.head + self.size - 1) % self.cap]
    def isFull(self):
        return self.size == self.cap
    def isEmpty(self):
        return self.size == 0

# Example: q = MyCircularQueue(3); q.enQueue(1); q.enQueue(2); q.Rear() -> 2; q.deQueue(); q.Front() -> 2
# Time: O(1) per operation, Space: O(k). Fixed array with head index and count.

def longest_valid_parentheses(s):
    stack = [-1]
    best = 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

# Example: longest_valid_parentheses(')()())') -> 4
# Time: O(n), Space: O(n). Stack of indices; base marker tracks last invalid point.

