class StackWithQueues:
    def __init__(self):
        self.q1 = deque()
        self.q2 = deque()
    def push(self, x):
        self.q2.append(x)
        while self.q1:
            self.q2.append(self.q1.popleft())
        self.q1, self.q2 = self.q2, self.q1
    def pop(self):
        return self.q1.popleft() if self.q1 else None
    def top(self):
        return self.q1[0] if self.q1 else None

# Example: s = StackWithQueues(); s.push(1); s.push(2); s.top() -> 2; s.pop() -> 2
