from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.cache = OrderedDict()
    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]
    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.cap:
            self.cache.popitem(last=False)

# Example: c = LRUCache(2); c.put(1,1); c.put(2,2); c.get(1) -> 1; c.put(3,3); c.get(2) -> -1
# Time: O(1) per operation, Space: O(capacity). OrderedDict as hash map + recency list.

from collections import deque

def reverse_stack(stack):
    q = deque()
    while stack:
        q.append(stack.pop())
    while q:
        stack.append(q.popleft())
    return stack

# Example: reverse_stack([1,2,3,4]) -> [4,3,2,1]
# Time: O(n), Space: O(n). Drain stack into queue, refill stack from queue front.

def sort_stack(stack):
    helper = []
    while stack:
        cur = stack.pop()
        while helper and helper[-1] > cur:
            stack.append(helper.pop())
        helper.append(cur)
    while helper:
        stack.append(helper.pop())
    return stack

# Example: sort_stack([3,1,4,2]) returns stack with 1 on top ascending downward.
# Time: O(n^2), Space: O(n). Transfer pattern: move larger elements back until sorted.

class QueueWithStacks:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []
    def enqueue(self, x):
        self.in_stack.append(x)
    def dequeue(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        return self.out_stack.pop() if self.out_stack else None

# Example: q = QueueWithStacks(); q.enqueue(1); q.enqueue(2); q.dequeue() -> 1
