def is_valid_permutation(s):
    balance = 0
    for ch in s:
        if ch == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

# Example: is_valid_permutation('(()())') -> True
# Time: O(n), Space: O(1). Running open-close balance check.

def postfix_to_infix(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            stack.append(f'({a} {t} {b})')
        else:
            stack.append(t)
    return stack[0]

# Example: postfix_to_infix(['a','b','+','c','*']) -> '((a + b) * c)'
# Time: O(n), Space: O(n). Stack builds parenthesized expressions bottom-up.

class MaxStack:
    def __init__(self):
        self.stack = []
        self.maxes = []
    def push(self, x):
        self.stack.append(x)
        if not self.maxes or x >= self.maxes[-1]:
            self.maxes.append(x)
    def pop(self):
        x = self.stack.pop()
        if self.maxes and x == self.maxes[-1]:
            self.maxes.pop()
        return x
    def top(self):
        return self.stack[-1]
    def getMax(self):
        return self.maxes[-1]

# Example: s = MaxStack(); s.push(5); s.push(1); s.push(5); s.getMax() -> 5; s.pop(); s.getMax() -> 5
# Time: O(1) per operation, Space: O(n). Max stack pushes only when >= current max.
